{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h1",
        "intro_text",
        "ranking_heading",
        "ranking_stack",
        "comparison_heading",
        "comparison_table",
        "top_recommendation_heading",
        "top_recommendation_card",
        "quick_actions_heading",
        "quick_actions_stack",
        "sources_heading",
        "sources_stack"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Vieux Lyon Bouchon Recommendations",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Based on your group of 4 and the need for high-quality gluten-free options in Vieux Lyon within a €50/person budget, here is the ranking:",
        "variant": "body"
      },
      "children": []
    },
    "ranking_heading": {
      "type": "Text",
      "props": {
        "text": "Ranking for Gluten-Free Dining",
        "variant": "h2"
      },
      "children": []
    },
    "ranking_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "les_fines_gueules_card",
        "aux_trois_maries_card",
        "le_laurencin_card"
      ]
    },
    "les_fines_gueules_card": {
      "type": "Card",
      "props": {},
      "children": [
        "les_fines_gueules_title",
        "les_fines_gueules_reason_label",
        "les_fines_gueules_reason_text"
      ]
    },
    "les_fines_gueules_title": {
      "type": "Text",
      "props": {
        "text": "1. Les Fines Gueules | Best Fit",
        "variant": "h3"
      },
      "children": []
    },
    "les_fines_gueules_reason_label": {
      "type": "Text",
      "props": {
        "text": "Reason:",
        "variant": "label"
      },
      "children": []
    },
    "les_fines_gueules_reason_text": {
      "type": "Text",
      "props": {
        "text": "This restaurant is the most knowledgeable about allergens and specifically offers gluten-free bread and dessert alternatives, ensuring a full experience for all guests.",
        "variant": "body"
      },
      "children": []
    },
    "aux_trois_maries_card": {
      "type": "Card",
      "props": {},
      "children": [
        "aux_trois_maries_title",
        "aux_trois_maries_reason_label",
        "aux_trois_maries_reason_text"
      ]
    },
    "aux_trois_maries_title": {
      "type": "Text",
      "props": {
        "text": "2. Aux Trois Maries | Good Alternative",
        "variant": "h3"
      },
      "children": []
    },
    "aux_trois_maries_reason_label": {
      "type": "Text",
      "props": {
        "text": "Reason:",
        "variant": "label"
      },
      "children": []
    },
    "aux_trois_maries_reason_text": {
      "type": "Text",
      "props": {
        "text": "While famous for flour-based quenelles, they can adapt most main courses and provide limited GF bread. The €35 set menu fits the budget well.",
        "variant": "body"
      },
      "children": []
    },
    "le_laurencin_card": {
      "type": "Card",
      "props": {},
      "children": [
        "le_laurencin_title",
        "le_laurencin_reason_label",
        "le_laurencin_reason_text"
      ]
    },
    "le_laurencin_title": {
      "type": "Text",
      "props": {
        "text": "3. Le Laurencin | Least Suitable",
        "variant": "h3"
      },
      "children": []
    },
    "le_laurencin_reason_label": {
      "type": "Text",
      "props": {
        "text": "Reason:",
        "variant": "label"
      },
      "children": []
    },
    "le_laurencin_reason_text": {
      "type": "Text",
      "props": {
        "text": "Gluten-free options are very restricted (salads/plain meat), and the loud environment may make communicating dietary needs more difficult.",
        "variant": "body"
      },
      "children": []
    },
    "comparison_heading": {
      "type": "Text",
      "props": {
        "text": "Restaurant Comparison Table",
        "variant": "h2"
      },
      "children": []
    },
    "comparison_table": {
      "type": "Table",
      "props": {
        "columns": [
          { "key": "restaurant", "label": "Restaurant" },
          { "key": "price", "label": "Price" },
          { "key": "gf_friendly", "label": "GF Friendly" },
          { "key": "atmosphere", "label": "Atmosphere" },
          { "key": "location", "label": "Location" }
        ],
        "rows": [
          { "restaurant": "Les Fines Gueules", "price": "~€45", "gf_friendly": "Excellent (Bread/Dessert)", "atmosphere": "High-end Bistro", "location": "Vieux Lyon" },
          { "restaurant": "Aux Trois Maries", "price": "€35", "gf_friendly": "Moderate (Mains only)", "atmosphere": "Traditional", "location": "Vieux Lyon" },
          { "restaurant": "Le Laurencin", "price": "€22", "gf_friendly": "Poor (Salads/Plain)", "atmosphere": "Busy/Loud Terrace", "location": "Vieux Lyon" }
        ],
        "domain": "comparison",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "top_recommendation_heading": {
      "type": "Text",
      "props": {
        "text": "Top Recommendation: Les Fines Gueules",
        "variant": "h2"
      },
      "children": []
    },
    "top_recommendation_card": {
      "type": "Card",
      "props": {},
      "children": [
        "top_rec_media_stack",
        "atmosphere_label",
        "atmosphere_text",
        "why_it_wins_label",
        "why_it_wins_text"
      ]
    },
    "top_rec_media_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "top_rec_image",
        "top_rec_icon"
      ]
    },
    "top_rec_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/7a/Lyon_Bouchon_interior.jpg/1200px-Lyon_Bouchon_interior.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "top_rec_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/star.svg"
      },
      "children": []
    },
    "atmosphere_label": {
      "type": "Text",
      "props": {
        "text": "Atmosphere:",
        "variant": "label"
      },
      "children": []
    },
    "atmosphere_text": {
      "type": "Text",
      "props": {
        "text": "A refined and knowledgeable bistro setting that balances traditional Lyonnais culinary roots with modern dietary awareness.",
        "variant": "body"
      },
      "children": []
    },
    "why_it_wins_label": {
      "type": "Text",
      "props": {
        "text": "Why it wins:",
        "variant": "label"
      },
      "children": []
    },
    "why_it_wins_text": {
      "type": "Text",
      "props": {
        "text": "It is the only option that offers a complete meal experience (including bread and dessert) for a gluten-free guest without compromising on quality.",
        "variant": "body"
      },
      "children": []
    },
    "quick_actions_heading": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "book_button",
        "guide_button"
      ]
    },
    "book_button": {
      "type": "Button",
      "props": {
        "label": "Book Les Fines Gueules"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.restaurant-lesfinesgueules.fr/"
          }
        }
      },
      "children": []
    },
    "guide_button": {
      "type": "Button",
      "props": {
        "label": "Vieux Lyon Guide"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.en.lyon-france.com/discover-lyon/vieux-lyon"
          }
        }
      },
      "children": []
    },
    "sources_heading": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "source_les_fines_gueules",
        "source_aux_trois_maries",
        "source_le_laurencin",
        "source_lyon_tourism"
      ]
    },
    "source_les_fines_gueules": {
      "type": "Button",
      "props": {
        "label": "Les Fines Gueules Official Site"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.restaurant-lesfinesgueules.fr/"
          }
        }
      },
      "children": []
    },
    "source_aux_trois_maries": {
      "type": "Button",
      "props": {
        "label": "Aux Trois Maries Info"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.lyon-france.com/restaurants/aux-trois-maries"
          }
        }
      },
      "children": []
    },
    "source_le_laurencin": {
      "type": "Button",
      "props": {
        "label": "Le Laurencin Reviews"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.tripadvisor.com/Restaurant_Review-g187265-d719324-Reviews-Le_Laurencin-Lyon_Rhone_Auvergne_Rhone_Alpes.html"
          }
        }
      },
      "children": []
    },
    "source_lyon_tourism": {
      "type": "Button",
      "props": {
        "label": "Vieux Lyon Tourism Guide"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.en.lyon-france.com/discover-lyon/vieux-lyon"
          }
        }
      },
      "children": []
    }
  }
}
